1	class ZimmTextInput extends HTMLElement {
2	  static get observedAttributes() {
3	    return [
4	      'label', 'placeholder', 'value', 'type', 'name',
5	      'helper-text', 'error-text',
6	      'disabled', 'inverse', 'trailing-icon', 'variant',
7	    ];
8	  }
9	
10	  constructor() {
11	    super();
12	    this.attachShadow({ mode: 'open' });
13	  }
14	
15	  connectedCallback() { this._render(); }
16	  attributeChangedCallback(name, oldValue, newValue) { if (oldValue === newValue) return; this._render(); }
17	
18	  _render() {
19	    const label       = this.getAttribute('label')        || '';
20	    const placeholder = this.getAttribute('placeholder')  || '';
21	    const value       = this.getAttribute('value')        || '';
22	    const type        = this.getAttribute('type')         || 'text';
23	    const name        = this.getAttribute('name')         || '';
24	    const helperText  = this.getAttribute('helper-text')  || '';
25	    const errorText   = this.getAttribute('error-text')   || '';
26	    const disabled    = this.hasAttribute('disabled');
27	    const trailingIcon = this.getAttribute('trailing-icon') || '';
28	    const variant     = this.getAttribute('variant') || 'flush';
29	
30	    const hasError  = !!errorText;
31	    const hasFilled = !!value;
32	    const isOutline = variant === 'outline';
33	    const helpId    = helperText ? 'help-msg'  : '';
34	    const errorId   = errorText  ? 'error-msg' : '';
35	    const ariaDesc  = [helpId, errorId].filter(Boolean).join(' ');
36	    const iconBase  = new URL('../icon/assets/', import.meta.url).href;
37	
38	    const rowClass = [
39	      'input-row',
40	      isOutline  ? 'is-outline'  : '',
41	      hasError   ? 'is-error'    : '',
42	      disabled   ? 'is-disabled' : '',
43	    ].filter(Boolean).join(' ');
44	
45	    const contentClass = ['content', hasFilled ? 'has-value' : ''].filter(Boolean).join(' ');
46	
47	    this.shadowRoot.innerHTML = `
48	      <style>
49	        :host { display: block; width: 100%; }
50	        * { box-sizing: border-box; }
51	
52	        .field {
53	          display: flex;
54	          flex-direction: column;
55	          gap: var(--zimm-scale-xs);
56	          width: 100%;
57	        }
58	
59	        /* ---- Input row: flush bottom-border style ---- */
60	        .input-row {
61	          display: flex;
62	          align-items: center;
63	          gap: var(--zimm-scale-xs);
64	          border-bottom: 1px solid var(--zimm-color-border-forms);
65	          padding: var(--zimm-scale-2xs) 0;
66	          position: relative;
67	          transition:
68	            border-color var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard),
69	            box-shadow   var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard);
70	        }
71	
72	        .input-row:hover        { border-bottom-color: var(--zimm-color-text-default); }
73	        .input-row:focus-within {
74	          border-bottom-color: var(--zimm-color-text-default);
75	          box-shadow: 0 1px 0 0 var(--zimm-color-text-default);
76	        }
77	        .input-row.is-error          { border-bottom-color: var(--zimm-color-status-error); }
78	        .input-row.is-error:hover,
79	        .input-row.is-error:focus-within { border-bottom-color: var(--zimm-color-status-error); }
80	        .input-row.is-disabled {
81	          border-bottom-color: color-mix(in srgb, var(--zimm-color-grey-300) 50%, transparent);
82	          pointer-events: none;
83	        }
84	
85	        /* ---- Outline variant: full border + horizontal padding ---- */
86	        .input-row.is-outline {
87	          border: 1px solid var(--zimm-color-border-forms);
88	          padding-left: var(--zimm-scale-s);
89	          padding-right: var(--zimm-scale-s);
90	        }
91	        .input-row.is-outline:hover             { border-color: var(--zimm-color-text-default); }
92	        .input-row.is-outline:focus-within {
93	          border-color: var(--zimm-color-text-default);
94	          box-shadow: 0 0 0 1px var(--zimm-color-text-default);
95	        }
96	        .input-row.is-outline.is-error          { border-color: var(--zimm-color-status-error); }
97	        .input-row.is-outline.is-error:hover,
98	        .input-row.is-outline.is-error:focus-within { border-color: var(--zimm-color-status-error); }
99	        .input-row.is-outline.is-disabled {
100	          border-color: color-mix(in srgb, var(--zimm-color-grey-300) 50%, transparent);
101	          background-color: color-mix(in srgb, var(--zimm-color-grey-100) 50%, transparent);
102	        }
103	
104	        /* Inverse (dark bg) — flush only; Outline has no inverse variant */
105	        :host([inverse]) .input-row              { border-bottom-color: var(--zimm-color-grey-white); }
106	        :host([inverse]) .input-row:hover        { border-bottom-color: var(--zimm-color-grey-white); }
107	        :host([inverse]) .input-row:focus-within {
108	          border-bottom-color: var(--zimm-color-grey-white);
109	          box-shadow: 0 1px 0 0 var(--zimm-color-grey-white);
110	        }
111	        :host([inverse]) .input-row.is-error     { border-bottom-color: var(--zimm-color-status-error-bg); }
112	        :host([inverse]) .input-row.is-error:hover,
113	        :host([inverse]) .input-row.is-error:focus-within { border-bottom-color: var(--zimm-color-status-error-bg); }
114	        :host([inverse]) .input-row.is-disabled  {
115	          border-bottom-color: var(--zimm-color-grey-white);
116	          background-color: transparent;
117	          opacity: 0.5;
118	        }
119	
120	        /* ---- Content: label + native input stacked ---- */
121	        .content {
122	          flex: 1;
123	          display: flex;
124	          flex-direction: column;
125	          justify-content: center;
126	          min-height: 36px; /* Figma content height; not in named scale */
127	          position: relative;
128	        }
129	
130	        /* ---- Floating label ---- */
131	        .float-label {
132	          position: absolute;
133	          top: 50%;
134	          transform: translateY(-50%);
135	          font-family: var(--zimm-font-family-body);
136	          font-weight: var(--zimm-font-weight-regular);
137	          font-size: var(--zimm-font-size-2xs);
138	          line-height: var(--zimm-font-lineheight-2xs);
139	          color: var(--zimm-color-text-default);
140	          pointer-events: none;
141	          transition:
142	            top                   var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard),
143	            transform             var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard),
144	            font-size             var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard),
145	            font-weight           var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard);
146	          white-space: nowrap;
147	          overflow: hidden;
148	          text-overflow: ellipsis;
149	          max-width: 100%;
150	          cursor: text;
151	        }
152	
153	        /* Floated: value present or field focused.
154	           top: 2px + line-height: 12px = label occupies rows 2-14px.
155	           Input is absolute bottom:0 height:20px = rows 16-36px. 2px gap. No overlap. */
156	        /* Floated: label colour shifts to secondary */
157	        .content.has-value .float-label,
158	        .input-row:focus-within .float-label {
159	          top: 2px;
160	          transform: translateY(0);
161	          font-size: var(--zimm-font-size-4xs);
162	          line-height: 12px;
163	          font-weight: var(--zimm-font-weight-medium);
164	          color: var(--zimm-color-text-secondary);
165	        }
166	
167	        /* Disabled: 50% opacity on label, floated or unfloated */
168	        .input-row.is-disabled .float-label {
169	          color: color-mix(in srgb, var(--zimm-color-text-default) 50%, transparent);
170	        }
