class ZimmTextInput extends HTMLElement {
  static get observedAttributes() {
    return [
      'label', 'placeholder', 'value', 'type', 'name',
      'helper-text', 'error-text',
      'disabled', 'inverse', 'trailing-icon', 'variant',
    ];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this._render(); }
  attributeChangedCallback(name, oldValue, newValue) { if (oldValue === newValue) return; this._render(); }

  _render() {
    const label       = this.getAttribute('label')        || '';
    const placeholder = this.getAttribute('placeholder')  || '';
    const value       = this.getAttribute('value')        || '';
    const type        = this.getAttribute('type')         || 'text';
    const name        = this.getAttribute('name')         || '';
    const helperText  = this.getAttribute('helper-text')  || '';
    const errorText   = this.getAttribute('error-text')   || '';
    const disabled    = this.hasAttribute('disabled');
    const trailingIcon = this.getAttribute('trailing-icon') || '';
    const variant     = this.getAttribute('variant') || 'flush';

    const hasError  = !!errorText;
    const hasFilled = !!value;
    const isOutline = variant === 'outline';
    const helpId    = helperText ? 'help-msg'  : '';
    const errorId   = errorText  ? 'error-msg' : '';
    const ariaDesc  = [helpId, errorId].filter(Boolean).join(' ');
    const iconBase  = new URL('../icon/assets/', import.meta.url).href;

    const rowClass = [
      'input-row',
      isOutline  ? 'is-outline'  : '',
      hasError   ? 'is-error'    : '',
      disabled   ? 'is-disabled' : '',
    ].filter(Boolean).join(' ');

    const contentClass = ['content', hasFilled ? 'has-value' : ''].filter(Boolean).join(' ');

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: block; width: 100%; }
        * { box-sizing: border-box; }

        .field {
          display: flex;
          flex-direction: column;
          gap: var(--zimm-scale-xs);
          width: 100%;
        }

        /* ---- Input row: flush bottom-border style ---- */
        .input-row {
          display: flex;
          align-items: center;
          gap: var(--zimm-scale-xs);
          border-bottom: 1px solid var(--zimm-color-border-forms);
          padding: var(--zimm-scale-2xs) 0;
          position: relative;
          transition:
            border-color var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard),
            box-shadow   var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard);
        }

        .input-row:hover        { border-bottom-color: var(--zimm-color-text-default); }
        .input-row:focus-within {
          border-bottom-color: var(--zimm-color-text-default);
          box-shadow: 0 1px 0 0 var(--zimm-color-text-default);
        }
        .input-row.is-error          { border-bottom-color: var(--zimm-color-status-error); }
        .input-row.is-error:hover,
        .input-row.is-error:focus-within { border-bottom-color: var(--zimm-color-status-error); }
        .input-row.is-disabled {
          border-bottom-color: color-mix(in srgb, var(--zimm-color-grey-300) 50%, transparent);
          pointer-events: none;
        }

        /* ---- Outline variant: full border + horizontal padding ---- */
        .input-row.is-outline {
          border: 1px solid var(--zimm-color-border-forms);
          padding-left: var(--zimm-scale-s);
          padding-right: var(--zimm-scale-s);
        }
        .input-row.is-outline:hover             { border-color: var(--zimm-color-text-default); }
        .input-row.is-outline:focus-within {
          border-color: var(--zimm-color-text-default);
          box-shadow: 0 0 0 1px var(--zimm-color-text-default);
        }
        .input-row.is-outline.is-error          { border-color: var(--zimm-color-status-error); }
        .input-row.is-outline.is-error:hover,
        .input-row.is-outline.is-error:focus-within { border-color: var(--zimm-color-status-error); }
        .input-row.is-outline.is-disabled {
          border-color: color-mix(in srgb, var(--zimm-color-grey-300) 50%, transparent);
          background-color: color-mix(in srgb, var(--zimm-color-grey-100) 50%, transparent);
        }

        /* Inverse (dark bg) — flush only; Outline has no inverse variant */
        :host([inverse]) .input-row              { border-bottom-color: var(--zimm-color-grey-white); }
        :host([inverse]) .input-row:hover        { border-bottom-color: var(--zimm-color-grey-white); }
        :host([inverse]) .input-row:focus-within {
          border-bottom-color: var(--zimm-color-grey-white);
          box-shadow: 0 1px 0 0 var(--zimm-color-grey-white);
        }
        :host([inverse]) .input-row.is-error     { border-bottom-color: var(--zimm-color-status-error-bg); }
        :host([inverse]) .input-row.is-error:hover,
        :host([inverse]) .input-row.is-error:focus-within { border-bottom-color: var(--zimm-color-status-error-bg); }
        :host([inverse]) .input-row.is-disabled  {
          border-bottom-color: var(--zimm-color-grey-white);
          background-color: transparent;
          opacity: 0.5;
        }

        /* ---- Content: label + native input stacked ---- */
        .content {
          flex: 1;
          display: flex;
          flex-direction: column;
          justify-content: center;
          min-height: 36px; /* Figma content height; not in named scale */
          position: relative;
        }

        /* ---- Floating label ---- */
        .float-label {
          position: absolute;
          top: 50%;
          transform: translateY(-50%);
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-regular);
          font-size: var(--zimm-font-size-2xs);
          line-height: var(--zimm-font-lineheight-2xs);
          color: var(--zimm-color-text-default);
          pointer-events: none;
          transition:
            top                   var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard),
            transform             var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard),
            font-size             var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard),
            font-weight           var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard);
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
          max-width: 100%;
          cursor: text;
        }

        /* Floated: value present or field focused.
           top: 2px + line-height: 12px = label occupies rows 2-14px.
           Input is absolute bottom:0 height:20px = rows 16-36px. 2px gap. No overlap. */
        /* Floated: label colour shifts to secondary */
        .content.has-value .float-label,
        .input-row:focus-within .float-label {
          top: 2px;
          transform: translateY(0);
          font-size: var(--zimm-font-size-4xs);
          line-height: 12px;
          font-weight: var(--zimm-font-weight-medium);
          color: var(--zimm-color-text-secondary);
        }

        /* Disabled: 50% opacity on label, floated or unfloated */
        .input-row.is-disabled .float-label {
          color: color-mix(in srgb, var(--zimm-color-text-default) 50%, transparent);
        }
        .input-row.is-disabled .content.has-value .float-label {
          color: color-mix(in srgb, var(--zimm-color-text-secondary) 50%, transparent);
        }

        /* Inverse: unfloated white, floated grey-300 */
        :host([inverse]) .float-label                        { color: var(--zimm-color-grey-white); }
        :host([inverse]) .content.has-value .float-label,
        :host([inverse]) .input-row:focus-within .float-label { color: var(--zimm-color-grey-300); }

        /* Inverse disabled: 50% opacity */
        :host([inverse]) .input-row.is-disabled .float-label {
          color: color-mix(in srgb, var(--zimm-color-grey-white) 50%, transparent);
        }
        :host([inverse]) .input-row.is-disabled .content.has-value .float-label {
          color: color-mix(in srgb, var(--zimm-color-grey-300) 50%, transparent);
        }

        /* ---- Native input ---- */
        .native-input {
          position: absolute;
          bottom: 0;
          left: 0;
          right: 0;
          width: 100%;
          height: 20px; /* Figma inputContainer height; not in named scale */
          background: transparent;
          border: none;
          outline: none;
          padding: 0;
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-regular);
          font-size: var(--zimm-font-size-2xs);
          line-height: var(--zimm-font-lineheight-2xs);
          color: var(--zimm-color-text-default);
          opacity: 0;
          transition: opacity var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard);
        }

        /* Show input when label has floated */
        .content.has-value .native-input,
        .input-row:focus-within .native-input { opacity: 1; }

        .native-input:disabled {
          color: var(--zimm-color-grey-300);
          -webkit-text-fill-color: var(--zimm-color-grey-300);
        }

        .native-input::placeholder { color: var(--zimm-color-text-secondary); opacity: 1; }
        .native-input:disabled::placeholder {
          color: color-mix(in srgb, var(--zimm-color-text-secondary) 50%, transparent);
        }

        /* Suppress all browser-native validation UI; the component handles its own error state */
        .native-input:invalid,
        .native-input:user-invalid {
          box-shadow: none;
          outline: none;
          color: inherit;
          -webkit-text-fill-color: inherit;
          text-decoration: none;
        }

        :host([inverse]) .native-input { color: var(--zimm-color-grey-white); }
        :host([inverse]) .native-input:disabled {
          color: var(--zimm-color-grey-300);
          -webkit-text-fill-color: var(--zimm-color-grey-300);
        }
        :host([inverse]) .native-input::placeholder { color: var(--zimm-color-grey-300); opacity: 1; }
        :host([inverse]) .native-input:disabled::placeholder {
          color: color-mix(in srgb, var(--zimm-color-grey-300) 50%, transparent);
        }

        /* ---- Trailing icon ---- */
        /* Icons are dark-stroke SVGs; invert to white on dark bg */
        .trail-icon {
          flex-shrink: 0;
          width: 16px;
          height: 16px;
          display: block;
        }
        :host([inverse]) .trail-icon { filter: invert(1); }

        /* ---- Helper / error text ---- */
        .help-text,
        .error-text {
          margin: 0;
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-regular);
          font-size: var(--zimm-font-size-2xs);
          line-height: var(--zimm-font-lineheight-2xs);
        }
        .help-text  { color: var(--zimm-color-text-secondary); }
        .error-text { color: var(--zimm-color-status-error); }

        :host([inverse]) .help-text  { color: var(--zimm-color-grey-300); }
        :host([inverse]) .error-text { color: var(--zimm-color-status-error-bg); }
      </style>

      <div class="field">
        <div class="${rowClass}">
          <div class="${contentClass}">
            <label class="float-label" for="native-input">${label}</label>
            <input
              id="native-input"
              class="native-input"
              type="${type}"
              value="${value}"
              placeholder="${placeholder}"
              ${name ? `name="${name}"` : ''}
              ${disabled    ? 'disabled'           : ''}
              ${hasError    ? 'aria-invalid="true"' : ''}
              ${ariaDesc    ? `aria-describedby="${ariaDesc}"` : ''}
            >
          </div>
          ${trailingIcon
            ? `<img class="trail-icon" src="${iconBase}${trailingIcon}.svg" alt="" aria-hidden="true">`
            : ''}
          <slot name="trailing"></slot>
        </div>
        ${helperText
          ? `<p id="help-msg" class="help-text">${helperText}</p>`
          : ''}
        ${errorText
          ? `<p id="error-msg" class="error-text" role="alert">${errorText}</p>`
          : ''}
      </div>
    `;

    const input   = this.shadowRoot.querySelector('.native-input');
    const content = this.shadowRoot.querySelector('.content');
    if (input && content) {
      input.addEventListener('input', (e) => {
        content.classList.toggle('has-value', e.target.value.length > 0);
      });
    }
  }
}

customElements.define('zimm-text-input', ZimmTextInput);

