  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this._render(); }
  attributeChangedCallback(name, oldValue, newValue) { if (oldValue === newValue) return; this._render(); }

  _render() {
    const placeholder = this.getAttribute('placeholder') || 'Search';
    const value       = this.getAttribute('value')       || '';
    const name        = this.getAttribute('name')        || '';
    const iconBase    = new URL('../icon/assets/', import.meta.url).href;

    const hasValue = !!value;
    const rowClass = ['input-row', hasValue ? 'has-value' : ''].filter(Boolean).join(' ');

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: block; width: 100%; }
        * { box-sizing: border-box; }

        .input-row {
          display: flex;
          align-items: center;
          gap: var(--zimm-scale-xs);
          border-bottom: 1px solid var(--zimm-color-border-forms);
          padding: var(--zimm-scale-2xs) 0;
          min-height: 36px;
          transition:
            border-color var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard),
            box-shadow   var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard);
        }

        .input-row:hover        { border-bottom-color: var(--zimm-color-text-default); }
        .input-row:focus-within {
          border-bottom-color: var(--zimm-color-text-default);
          box-shadow: 0 1px 0 0 var(--zimm-color-text-default);
        }

        :host([inverse]) .input-row              { border-bottom-color: var(--zimm-color-grey-white); }
        :host([inverse]) .input-row:hover        { border-bottom-color: var(--zimm-color-grey-white); }
        :host([inverse]) .input-row:focus-within {
          border-bottom-color: var(--zimm-color-grey-white);
          box-shadow: 0 1px 0 0 var(--zimm-color-grey-white);
        }

        .native-input {
          flex: 1;
          background: transparent;
          border: none;
          outline: none;
          padding: 0;
          appearance: none;
          -webkit-appearance: none;
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-regular);
          font-size: var(--zimm-font-size-2xs);
          line-height: var(--zimm-font-lineheight-2xs);
          color: var(--zimm-color-text-default);
          min-height: 20px;
        }

        .native-input::-webkit-search-cancel-button,
        .native-input::-webkit-search-decoration { display: none; }

        .native-input::placeholder { color: var(--zimm-color-text-secondary); opacity: 1; }

        :host([inverse]) .native-input              { color: var(--zimm-color-grey-white); }
        :host([inverse]) .native-input::placeholder { color: var(--zimm-color-grey-300); opacity: 1; }

        /* Trailing icon slot: search shown by default, clear shown when has-value */
        .trail-search,
        .trail-clear {
          flex-shrink: 0;
          width: 20px;
          height: 20px;
          display: flex;
          align-items: center;
          justify-content: center;
        }

        .trail-search img,
        .trail-clear img { width: 20px; height: 20px; display: block; }

        .trail-clear {
          padding: 0;
          background: none;
          border: none;
          cursor: pointer;
          display: none;
        }
        .trail-clear:focus-visible {
          outline: 2px solid var(--zimm-color-border-focus);
          outline-offset: 2px;
          border-radius: 2px;
        }

        .input-row.has-value .trail-search { display: none; }
        .input-row.has-value .trail-clear  { display: flex; }

        :host([variant="bare"]) .trail-search { display: none; }

        :host([inverse]) .trail-search img { filter: invert(1); }
        :host([inverse]) .trail-clear  img { filter: invert(1); }
        :host([inverse]) .trail-clear:focus-visible {
          outline-color: var(--zimm-color-grey-white);
        }
      </style>

      <div class="${rowClass}">
        <input
          class="native-input"
          type="search"
          placeholder="${placeholder}"
          value="${value}"
          ${name ? `name="${name}"` : ''}
        >
        <span class="trail-search" aria-hidden="true">
          <img src="${iconBase}search.svg" alt="">
        </span>
        <button class="trail-clear" type="button" aria-label="Clear search">
          <img src="${iconBase}close.svg" alt="">
        </button>
      </div>
    `;

    const input    = this.shadowRoot.querySelector('.native-input');
    const row      = this.shadowRoot.querySelector('.input-row');
    const clearBtn = this.shadowRoot.querySelector('.trail-clear');

    input.addEventListener('input', () => {
      row.classList.toggle('has-value', input.value.length > 0);
    });

    clearBtn.addEventListener('click', () => {
      input.value = '';
      row.classList.remove('has-value');
      input.focus();
    });
  }
}

customElements.define('zimm-search', ZimmSearch);

