309	        .right-mobile  { display: flex; }
310	
311	        /* Mobile hamburger icon states */
312	        .icon-close-mobile { display: none; }
313	        :host([active]) .icon-menu         { display: none; }
314	        :host([active]) .icon-close-mobile { display: flex; }
315	
316	        /* ---- Tablet: 768px+ ---- */
317	        @media (min-width: 768px) {
318	          nav {
319	            align-items: center;
320	            padding: var(--zimm-scale-4xl) var(--zimm-scale-1000);
321	          }
322	          .hamburger-btn { display: none; }
323	          .nav-links     { display: flex; gap: var(--zimm-scale-1000); align-items: center; }
324	          .right-mobile  { display: none; }
325	          .right-tablet  { display: flex; align-items: center; }
326	        }
327	
328	        /* ---- Desktop: 1024px+ ---- */
329	        @media (min-width: 1024px) {
330	          .right-tablet  { display: none; }
331	          .right-desktop { display: flex; align-items: center; gap: var(--zimm-scale-500); }
332	        }
333	
334	        /* ---- Active overrides: tablet+ ---- */
335	        @media (min-width: 768px) {
336	          :host([active]) .right-tablet { display: none; }
337	          :host([active]) .right-active { display: flex; align-items: center; gap: var(--zimm-scale-200); }
338	          :host([active]) .right-active zimm-icon { margin-bottom: 4.5px; }
339	        }
340	
341	        @media (min-width: 1024px) {
342	          :host([active]) .right-desktop { display: none; }
343	          :host([active]) .right-active  { display: flex; }
344	        }
345	
346	        /* ---- Shared ---- */
347	        .icon-group {
348	          display: flex;
349	          gap: var(--zimm-scale-300);
350	          align-items: center;
351	        }
352	
353	        .search-trigger { cursor: pointer; }
354	
355	        .search-trigger-field {
356	          display: flex;
357	          align-items: center;
358	          align-self: stretch;
359	          border-bottom: 1px solid var(--zimm-color-border-forms);
360	          cursor: pointer;
361	          width: 180px;
362	        }
363	
364	        .search-trigger-label {
365	          flex: 1;
366	          font-family: var(--zimm-font-family-body);
367	          font-weight: var(--zimm-font-weight-medium);
368	          font-size: var(--zimm-font-size-3xs);
369	          line-height: normal;
370	          letter-spacing: var(--zimm-font-letterspacing-sm);
371	          text-transform: uppercase;
372	          color: var(--zimm-color-text-default);
373	          white-space: nowrap;
374	          user-select: none;
375	        }
376	
377	        .hamburger-btn {
378	          background: none;
379	          border: none;
