const _NAV_LABELS = ['New', 'Clothing', 'Accessories', 'Collections', 'Z.Immerse'];

class ZimmNavigation extends HTMLElement {
  static get observedAttributes() {
    return ['active'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this._handleClick    = this._handleClick.bind(this);
    this._activeIndex    = -1;
    this._mobileView     = null; // null | 'home' | 0-4
    this._prevMobileView = null;
  }

  connectedCallback() {
    this._render();
    this.shadowRoot.addEventListener('click', this._handleClick);
    if (this.hasAttribute('active')) {
      this._updateActiveState();
    }
  }

  disconnectedCallback() {
    this.shadowRoot.removeEventListener('click', this._handleClick);
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;
    this._updateActiveState();
  }

  _isMobile() {
    return window.matchMedia('(max-width: 767px)').matches;
  }

  _mobileCloseTransition() {
    if (!this._isMobile()) return;
    this.classList.add('mobile-closing');
    setTimeout(() => this.classList.remove('mobile-closing'), 300);
  }

  _handleClick(e) {
    const inMobileClose  = e.target.closest('.mobile-close-btn');
    const inMobileBack   = e.target.closest('.mobile-back-btn');
    const inMobileNavBtn = e.target.closest('.mobile-nav-btn');
    const inHamburger    = e.target.closest('.hamburger-btn');
    const inNavLinks     = e.target.closest('.nav-links');
    const inClose        = e.target.closest('.right-active');

    if (inMobileClose) {
      this._mobileCloseTransition();
      this._activeIndex    = -1;
      this._mobileView     = null;
      this._prevMobileView = null;
      this.removeAttribute('active');
      this._syncMobileView();
      this._updateActiveState();

    } else if (inMobileBack) {
      this._mobileView = 'home';
      this._syncMobileView();

    } else if (inMobileNavBtn) {
      this._mobileView = parseInt(inMobileNavBtn.dataset.index);
      this._syncMobileView();

    } else if (inHamburger) {
      this.toggleAttribute('active');
      if (this.hasAttribute('active')) {
        if (this._isMobile()) {
          this._mobileView = 'home';
          this._syncMobileView();
        }
      } else {
        this._mobileCloseTransition();
        this._activeIndex    = -1;
        this._mobileView     = null;
        this._prevMobileView = null;
        this._syncNavItems();
        this._syncPanelSection();
        this._syncMobileView();
      }
      this._updateActiveState();

    } else if (inNavLinks) {
      const navItem = e.target.closest('zimm-nav-item');
      if (!navItem) return;
      const items = [...this.shadowRoot.querySelectorAll('.nav-links zimm-nav-item')];
      const idx   = items.indexOf(navItem);
      if (idx === this._activeIndex) {
        this._activeIndex = -1;
        this.removeAttribute('active');
      } else {
        this._activeIndex = idx;
        this.setAttribute('active', '');
      }
      this._syncNavItems(items);
      this._syncPanelSection();
      this._updateActiveState();

    } else if (e.target.closest('.search-trigger')) {
      this.dispatchEvent(new CustomEvent('zimm-search-open', { bubbles: true, composed: true }));

    } else if (inClose) {
      this._activeIndex = -1;
      this.removeAttribute('active');
      this._syncNavItems();
      this._syncPanelSection();
      this._updateActiveState();
    }
  }

  _syncNavItems(items) {
    const navItems = items || [...this.shadowRoot.querySelectorAll('.nav-links zimm-nav-item')];
    navItems.forEach((item, i) => {
      if (i === this._activeIndex) item.setAttribute('active', '');
      else item.removeAttribute('active');
    });
  }

  _syncPanelSection() {
    const sections  = [...this.shadowRoot.querySelectorAll('.panel-section')];
    const isClosing = this._activeIndex === -1;

    sections.forEach((s, i) => {
      const isActive  = i === this._activeIndex;
      const wasActive = s.classList.contains('is-active');
      const menus     = s.querySelector('slot')?.assignedElements() ?? [];

      if (isActive) {
        s.classList.add('is-active');
        menus.forEach(m => {
          m.removeAttribute('closing');
          requestAnimationFrame(() => m.setAttribute('open', ''));
        });
      } else if (wasActive && isClosing) {
        menus.forEach(m => {
          m.removeAttribute('open');
          m.setAttribute('closing', '');
        });
        setTimeout(() => {
          s.classList.remove('is-active');
          menus.forEach(m => m.removeAttribute('closing'));
        }, 300);
      } else {
        s.classList.remove('is-active');
        menus.forEach(m => {
          m.removeAttribute('open');
          m.removeAttribute('closing');
        });
      }
    });
  }

  _syncMobileView() {
    const root       = this.shadowRoot;
    const panel      = root.querySelector('.menu-panel');
    const homeEl     = root.querySelector('.mobile-home');
    const subContent = root.querySelector('.mobile-sub-content');
    const sections   = [...root.querySelectorAll('.panel-section')];

    if (!panel) return;

    const prev = this._prevMobileView;
    this._prevMobileView = this._mobileView;

    if (!this._isMobile() || this._mobileView === null) {
      panel.classList.remove('is-mobile-sub');
      if (homeEl)     homeEl.style.cssText     = '';
      if (subContent) subContent.style.cssText = '';
      sections.forEach(s => {
        s.classList.remove('is-active');
        (s.querySelector('slot')?.assignedElements() ?? []).forEach(m => {
          m.removeAttribute('mobile');
          m.removeAttribute('open');
          m.removeAttribute('closing');
        });
      });
      return;
    }

    if (this._mobileView === 'home') {
      sections.forEach(s => {
        s.classList.remove('is-active');
        (s.querySelector('slot')?.assignedElements() ?? []).forEach(m => {
          m.removeAttribute('mobile');
          m.removeAttribute('open');
          m.removeAttribute('closing');
        });
      });

      if (prev !== null && prev !== 'home') {
        this._animateTransition(homeEl, subContent, panel, 'back');
      } else {
        panel.classList.remove('is-mobile-sub');
        homeEl.style.display     = 'flex';
        subContent.style.display = 'none';
        homeEl.style.animation   = '';
      }

    } else {
      const idx = this._mobileView;
      sections.forEach((s, i) => {
        const menus = s.querySelector('slot')?.assignedElements() ?? [];
        if (i === idx) {
          s.classList.add('is-active');
          menus.forEach(m => {
            m.removeAttribute('open');
            m.removeAttribute('closing');
            m.setAttribute('mobile', '');
          });
        } else {
          s.classList.remove('is-active');
          menus.forEach(m => {
            m.removeAttribute('mobile');
            m.removeAttribute('open');
            m.removeAttribute('closing');
          });
        }
      });

      if (prev === 'home' || prev === null) {
        this._animateTransition(homeEl, subContent, panel, 'forward');
      } else {
        panel.classList.add('is-mobile-sub');
        subContent.style.display = 'flex';
      }
    }
  }

  _animateTransition(homeEl, subContent, panel, direction) {
    const dur = '300ms var(--zimm-motion-easing-slides)';

    homeEl.style.animation     = '';
    subContent.style.animation = '';

    if (direction === 'forward') {
      // Button crossfade: X fades out, chevron fades in
      panel.classList.add('is-mobile-sub');
      homeEl.style.display       = 'flex';
      subContent.style.display   = 'flex';
      homeEl.style.animation     = `m-slide-out-left ${dur} both`;
      subContent.style.animation = `m-slide-in-right ${dur} both`;

      homeEl.addEventListener('animationend', () => {
        homeEl.style.display       = 'none';
        homeEl.style.animation     = '';
        subContent.style.animation = '';
      }, { once: true });

    } else {
      // Button crossfade: chevron fades out, X fades in (immediate, before slide completes)
      panel.classList.remove('is-mobile-sub');
      homeEl.style.display       = 'flex';
      homeEl.style.animation     = `m-slide-in-left ${dur} both`;
      subContent.style.animation = `m-slide-out-right ${dur} both`;

      subContent.addEventListener('animationend', () => {
        subContent.style.display   = 'none';
        homeEl.style.animation     = '';
        subContent.style.animation = '';
      }, { once: true });
    }
  }

  _updateActiveState() {
    const active = this.hasAttribute('active');
    const root   = this.shadowRoot;
    if (!root.querySelector('nav')) return;

    const btn = root.querySelector('.hamburger-btn');
    if (btn) {
      btn.setAttribute('aria-expanded', String(active));
      btn.setAttribute('aria-label', active ? 'Close menu' : 'Open menu');
    }

    const panel = root.querySelector('.menu-panel');
    if (panel) {
      panel.setAttribute('aria-hidden', String(!active));
    }
  }

  _render() {
    this.shadowRoot.innerHTML = `
      <style>
        :host {
          display: block;
          position: relative;
        }

        nav {
          display: flex;
          justify-content: space-between;
          align-items: flex-start;
          background-color: var(--zimm-color-bg-07);
          box-sizing: border-box;
          width: 100%;
          padding: var(--zimm-scale-600) var(--zimm-scale-800);
        }

        /* ---- Visibility defaults: mobile ---- */
        .hamburger-btn { display: flex; }
        .nav-links     { display: none; }
        .right-active  { display: none; }
        .right-desktop { display: none; }
        .right-tablet  { display: none; }
        .right-mobile  { display: flex; }

        /* Mobile hamburger icon states */
        .icon-close-mobile { display: none; }
        :host([active]) .icon-menu         { display: none; }
        :host([active]) .icon-close-mobile { display: flex; }

        /* ---- Tablet: 768px+ ---- */
        @media (min-width: 768px) {
          nav {
            align-items: center;
            padding: var(--zimm-scale-4xl) var(--zimm-scale-1000);
          }
          .hamburger-btn { display: none; }
          .nav-links     { display: flex; gap: var(--zimm-scale-1000); align-items: center; }
          .right-mobile  { display: none; }
          .right-tablet  { display: flex; align-items: center; }
        }

        /* ---- Desktop: 1024px+ ---- */
        @media (min-width: 1024px) {
          .right-tablet  { display: none; }
          .right-desktop { display: flex; align-items: center; gap: var(--zimm-scale-500); }
        }

        /* ---- Active overrides: tablet+ ---- */
        @media (min-width: 768px) {
          :host([active]) .right-tablet { display: none; }
          :host([active]) .right-active { display: flex; align-items: center; gap: var(--zimm-scale-200); }
          :host([active]) .right-active zimm-icon { margin-bottom: 4.5px; }
        }

        @media (min-width: 1024px) {
          :host([active]) .right-desktop { display: none; }
          :host([active]) .right-active  { display: flex; }
        }

        /* ---- Shared ---- */
        .icon-group {
          display: flex;
          gap: var(--zimm-scale-300);
          align-items: center;
        }

        .search-trigger { cursor: pointer; }

        .search-trigger-field {
          display: flex;
          align-items: center;
          align-self: stretch;
          border-bottom: 1px solid var(--zimm-color-border-forms);
          cursor: pointer;
          width: 180px;
        }

        .search-trigger-label {
          flex: 1;
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-3xs);
          line-height: normal;
          letter-spacing: var(--zimm-font-letterspacing-sm);
          text-transform: uppercase;
          color: var(--zimm-color-text-default);
          white-space: nowrap;
          user-select: none;
        }

        .hamburger-btn {
          background: none;
          border: none;
          padding: 0;
          cursor: pointer;
          align-items: center;
        }

        .hamburger-btn:focus-visible {
          outline: 2px solid var(--zimm-color-border-focus);
          outline-offset: 2px;
        }

        /* ---- Mega menu panel ---- */
        .menu-panel {
          position: absolute;
          top: 100%;
          left: 0;
          width: 100%;
          background-color: var(--zimm-color-bg-07);
          overflow: hidden;
          height: 0;
          transition: height 300ms var(--zimm-motion-easing-slides);
          z-index: 100;
        }

        :host([active]) .menu-panel {
          height: 100vh;
        }

        /* Mobile: hide nav bar while panel is open or closing */
        @media (max-width: 767px) {
          :host([active]) nav,
          :host(.mobile-closing) nav { display: none; }
        }

        /* Mobile: fixed overlay, flex column so chrome + content area stack */
        @media (max-width: 767px) {
          :host([active]) .menu-panel {
            position: fixed;
            top: 0;
            left: 0;
            height: 100dvh;
            display: flex;
            flex-direction: column;
          }
        }

        @media (min-width: 1024px) {
          :host([active]) .menu-panel {
            height: 750px;
          }
        }

        .panel-section           { display: none; height: 100%; }
        .panel-section.is-active { display: block; }

        /* ---- Mobile persistent chrome: close/back crossfade, icons stay put ---- */
        .mobile-chrome { display: none; }

        @media (max-width: 767px) {
          .mobile-chrome {
            display: flex;
            flex-shrink: 0;
            justify-content: space-between;
            align-items: center;
            padding: var(--zimm-scale-600) var(--zimm-scale-800);
            background: var(--zimm-color-bg-07);
          }
        }

        @media (min-width: 768px) {
          .mobile-chrome { display: none !important; }
        }

        /* Both buttons occupy the same 20x20 slot, crossfading over each other */
        .mobile-chrome-left {
          position: relative;
          width: 20px;
          height: 20px;
          flex-shrink: 0;
        }

        .mobile-close-btn,
        .mobile-back-btn {
          position: absolute;
          top: 0;
          left: 0;
          background: none;
          border: none;
          padding: 0;
          cursor: pointer;
          display: flex;
          align-items: center;
          transition: opacity 200ms var(--zimm-motion-easing-fades);
        }

        .mobile-close-btn:focus-visible,
        .mobile-back-btn:focus-visible {
          outline: 2px solid var(--zimm-color-border-focus);
          outline-offset: 2px;
        }

        /* Home state: X visible, chevron hidden */
        .mobile-close-btn { opacity: 1; pointer-events: auto; }
        .mobile-back-btn  { opacity: 0; pointer-events: none; }

        /* Sub state: X fades out, chevron fades in */
        .menu-panel.is-mobile-sub .mobile-close-btn { opacity: 0; pointer-events: none; }
        .menu-panel.is-mobile-sub .mobile-back-btn  { opacity: 1; pointer-events: auto; }

        /* ---- Slide transition keyframes ---- */
        @keyframes m-slide-in-right  { from { transform: translateX(100%); }  to { transform: translateX(0); } }
        @keyframes m-slide-out-left  { from { transform: translateX(0); }     to { transform: translateX(-100%); } }
        @keyframes m-slide-in-left   { from { transform: translateX(-100%); } to { transform: translateX(0); } }
        @keyframes m-slide-out-right { from { transform: translateX(0); }     to { transform: translateX(100%); } }

        /* ---- Mobile content wrap: slide container on mobile, transparent on desktop ---- */
        /* display: contents keeps panel sections as direct panel children for desktop height */
        .mobile-content-wrap { display: contents; }

        @media (max-width: 767px) {
          .mobile-content-wrap {
            display: block;
            flex: 1;
            min-height: 0;
            position: relative;
            overflow: hidden;
          }
        }

        /* ---- Home view ---- */
        .mobile-home {
          display: none;
          flex-direction: column;
          background: var(--zimm-color-bg-07);
          overflow-y: auto;
        }

        @media (max-width: 767px) {
          .mobile-home {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
          }
        }

        @media (min-width: 768px) {
          .mobile-home { display: none !important; }
        }

        /* ---- Sub content: transparent on desktop, slide panel on mobile ---- */
        /* display: contents (nested with mobile-content-wrap) keeps desktop height chain intact */
        .mobile-sub-content { display: contents; }

        @media (max-width: 767px) {
          .mobile-sub-content {
            display: none;
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            flex-direction: column;
            background: var(--zimm-color-bg-07);
          }
          /* Active section fills sub content when JS sets display: flex */
          .mobile-sub-content .panel-section.is-active {
            height: auto;
            flex: 1;
            display: flex;
            flex-direction: column;
            overflow: hidden;
          }
          .mobile-sub-content .panel-section.is-active > slot {
            display: flex;
            flex: 1;
            flex-direction: column;
            min-height: 0;
          }
        }

        /* Mega menu fills slot when in mobile mode */
        ::slotted([mobile]) {
          flex: 1;
          min-height: 0;
        }

        /* Nav item list (home state) */
        .mobile-nav-list {
          display: flex;
          flex-direction: column;
          padding: var(--zimm-scale-4xl) var(--zimm-scale-800) var(--zimm-scale-800);
          gap: var(--zimm-scale-600);
        }

        .mobile-nav-btn {
          background: none;
          border: none;
          padding: 0;
          cursor: pointer;
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-xs);
          letter-spacing: var(--zimm-font-letterspacing-footer);
          text-transform: uppercase;
          color: var(--zimm-color-text-default);
          text-align: left;
        }

        .mobile-nav-btn:focus-visible {
          outline: 2px solid var(--zimm-color-border-focus);
          outline-offset: 2px;
        }

        /* Utility links slot (home state) */
        .mobile-utility-wrap {
          padding: var(--zimm-scale-1000) var(--zimm-scale-800);
          display: flex;
          flex-direction: column;
          gap: var(--zimm-scale-600);
        }

        ::slotted(a) {
          display: block;
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-3xs);
          letter-spacing: var(--zimm-font-letterspacing-footer);
          text-transform: uppercase;
          color: var(--zimm-color-text-default);
          text-decoration: none;
        }
      </style>

      <header role="banner">
        <nav aria-label="Main navigation">

          <button class="hamburger-btn"
                  aria-expanded="false"
                  aria-controls="menu-panel"
                  aria-label="Open menu">
            <zimm-icon class="icon-menu"         type="menu"  size="20" aria-hidden="true"></zimm-icon>
            <zimm-icon class="icon-close-mobile" type="close" size="20" aria-hidden="true"></zimm-icon>
          </button>

          <div class="nav-links">
            <zimm-nav-item label="New"></zimm-nav-item>
            <zimm-nav-item label="Clothing"></zimm-nav-item>
            <zimm-nav-item label="Accessories"></zimm-nav-item>
            <zimm-nav-item label="Collections"></zimm-nav-item>
            <zimm-nav-item label="Z.Immerse"></zimm-nav-item>
          </div>

          <div class="right-active">
            <zimm-nav-item label="Close"></zimm-nav-item>
            <zimm-icon type="close" size="20" aria-hidden="true"></zimm-icon>
          </div>

          <div class="right-desktop">
            <div class="search-trigger-field search-trigger" role="button" tabindex="0" aria-label="Open search">
              <span class="search-trigger-label">Search</span>
            </div>
            <div class="icon-group">
              <zimm-icon type="profile"  size="20" aria-label="Account"></zimm-icon>
              <zimm-icon type="wishlist" size="20" aria-label="Wishlist"></zimm-icon>
              <zimm-icon type="bag"      size="20" aria-label="Bag"></zimm-icon>
            </div>
          </div>

          <div class="right-tablet">
            <div class="icon-group">
              <zimm-icon class="search-trigger" type="search" size="20" aria-label="Open search"></zimm-icon>
              <zimm-icon type="profile"  size="20" aria-label="Account"></zimm-icon>
              <zimm-icon type="wishlist" size="20" aria-label="Wishlist"></zimm-icon>
              <zimm-icon type="bag"      size="20" aria-label="Bag"></zimm-icon>
            </div>
          </div>

          <div class="right-mobile">
            <div class="icon-group">
              <zimm-icon class="search-trigger" type="search" size="20" aria-label="Open search"></zimm-icon>
              <zimm-icon type="bag"    size="20" aria-label="Bag"></zimm-icon>
            </div>
          </div>

        </nav>

        <div class="menu-panel" id="menu-panel" aria-hidden="true">

          <!-- Persistent chrome: icons stay put, X and chevron crossfade in place -->
          <div class="mobile-chrome">
            <div class="mobile-chrome-left">
              <button class="mobile-close-btn" aria-label="Close menu">
                <zimm-icon type="close" size="20" aria-hidden="true"></zimm-icon>
              </button>
              <button class="mobile-back-btn" aria-label="Back">
                <zimm-icon type="chevron-left" size="20" aria-hidden="true"></zimm-icon>
              </button>
            </div>
            <div class="icon-group">
              <zimm-icon class="search-trigger" type="search" size="20" aria-label="Open search"></zimm-icon>
              <zimm-icon type="bag"    size="20" aria-label="Bag"></zimm-icon>
            </div>
          </div>

          <!-- Slide container: home and sub panels animate within this -->
          <div class="mobile-content-wrap">

            <!-- Home view (nav list + utility) -->
            <div class="mobile-home">
              <div class="mobile-nav-list">
                <button class="mobile-nav-btn" data-index="0">New</button>
                <button class="mobile-nav-btn" data-index="1">Clothing</button>
                <button class="mobile-nav-btn" data-index="2">Accessories</button>
                <button class="mobile-nav-btn" data-index="3">Collections</button>
                <button class="mobile-nav-btn" data-index="4">Z.Immerse</button>
              </div>
              <div class="mobile-utility-wrap">
                <slot name="mobile-utility"></slot>
              </div>
            </div>

            <!-- Sub content: panel sections slide in from right -->
            <div class="mobile-sub-content">
              <div class="panel-section"><slot name="menu-new"></slot></div>
              <div class="panel-section"><slot name="menu-clothing"></slot></div>
              <div class="panel-section"><slot name="menu-accessories"></slot></div>
              <div class="panel-section"><slot name="menu-collections"></slot></div>
              <div class="panel-section"><slot name="menu-z-immerse"></slot></div>
            </div>

          </div>

        </div>
      </header>
    `;
  }
}

customElements.define('zimm-navigation', ZimmNavigation);

