const ASSETS = new URL('./assets/', import.meta.url).href;

const SIZE_TOKEN = { '20': 'lg', '16': 'md', '12': 'sm' };

const VALID_TYPES = new Set([
  'arrow-down', 'arrow-up', 'arrow-link', 'bag', 'calendar', 'carousel',
  'carousel-selected', 'chat', 'check', 'chevron-down', 'chevron-left',
  'chevron-right', 'chevron-up', 'close', 'delete', 'edit', 'external-link',
  'info', 'location', 'menu', 'minus', 'mute', 'password', 'pause', 'play',
  'plus', 'profile', 'search', 'share', 'share-2', 'wishlist', 'wishlist-selected',
  'phone', 'whatsapp', 'email'
]);

const CSS_TYPES = new Set(['carousel', 'carousel-selected']);

class ZimmIcon extends HTMLElement {
  static get observedAttributes() {
    return ['type', 'size', 'aria-label', 'aria-hidden'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this._render(); }
  attributeChangedCallback(name, oldValue, newValue) { if (oldValue === newValue) return; this._render(); }

  _render() {
    const type     = VALID_TYPES.has(this.getAttribute('type')) ? this.getAttribute('type') : 'menu';
    const size     = ['20', '16', '12'].includes(this.getAttribute('size')) ? this.getAttribute('size') : '20';
    const sizeVal  = parseInt(size, 10);
    const token    = SIZE_TOKEN[size] || 'lg';
    const isHidden = this.getAttribute('aria-hidden') === 'true';
    const label    = this.getAttribute('aria-label') || type.replace(/-/g, ' ');

    let content;
    if (CSS_TYPES.has(type)) {
      const dim = Math.round(sizeVal * 0.6);
      content = `
        <span
          class="css-icon${type === 'carousel-selected' ? ' selected' : ''}"
          style="width:${dim}px;height:${dim}px;"
          ${isHidden ? 'aria-hidden="true"' : `role="img" aria-label="${label}"`}
        ></span>`;
    } else {
      content = `
        <img
          src="${ASSETS}${type}.svg"
          alt="${isHidden ? '' : label}"
          ${isHidden ? 'aria-hidden="true"' : 'role="img"'}
          draggable="false"
        >`;
    }

    this.shadowRoot.innerHTML = `
      <style>
        :host {
          display: inline-flex;
          align-items: center;
          justify-content: center;
          width: var(--zimm-icon-size-${token});
          height: var(--zimm-icon-size-${token});
          flex-shrink: 0;
        }
        img { display: block; width: 100%; height: 100%; }
        .css-icon {
          display: inline-block;
          border: var(--zimm-border-width-default) solid currentColor;
          transform: rotate(45deg);
          flex-shrink: 0;
          box-sizing: border-box;
        }
        .css-icon.selected { background: currentColor; }
      </style>
      ${content}
    `;
  }
}

customElements.define('zimm-icon', ZimmIcon);

